import { describe, test, expect } from 'bun:test';
import { sha512 } from './sha512.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha = sha512.factory(_ba, _utf8);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));
const hashBytes = (ui8) => toHex(_sha.hash(_ba.ui8_to_ba(ui8)));

describe('sha512 module', () => {

    test('module metadata', () => {
        expect(sha512.name).toBe('sha512');
        expect(sha512.dependencies).toEqual(['bitArray', 'utf8']);
    });

    describe('FIPS-180 vectors', () => {
        test('empty string', () => {
            expect(toHex(_sha.hash('')))
                .toBe('cf83e1357eefb8bdf1542850d66d8007d620e4050b5715dc83f4a921d36ce9ce47d0d13c5d85f2b0ff8318d2877eec2f63b931bd47417a81a538327af927da3e');
        });

        test('"abc"', () => {
            expect(toHex(_sha.hash('abc')))
                .toBe('ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f');
        });

        test('896-bit message', () => {
            const msg = 'abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu';
            expect(toHex(_sha.hash(msg)))
                .toBe('8e959b75dae313da8cf4f72814fc143f8f7779c6eb9f7fa17299aeadb6889018501d289e4900f7e4331b99dec4b5433ac7d329eeb6dd26545e96e55b874be909');
        });
    });

    describe('streaming', () => {
        test('chunked update matches one-shot', () => {
            const oneShot = toHex(_sha.hash('streaming-input-chunked-test'));
            const h = new _sha.fn();
            h.update('streaming-');
            h.update('input-');
            h.update('chunked-test');
            expect(toHex(h.finalize())).toBe(oneShot);
        });

        test('digest is 512 bits (16 x 32-bit words)', () => {
            const out = _sha.hash('hello');
            expect(out.length).toBe(16);
        });
    });
});

